// Builds the paste-ready n8n Code nodes for the T-Center takeover + friction
// changes from lib/bot/*.mjs, so the live bot runs the same bytes the unit tests
// run. Never edit the generated files — edit the module and re-run:
//
//   node scripts/n8n/build-tcenter-nodes.mjs          # write the files
//   node scripts/n8n/build-tcenter-nodes.mjs --check  # exit 1 if they are stale
//
// tests/unit/tcenter-code-nodes.test.ts executes every generated node against a
// fake n8n runtime and fails if the committed files drift from this build.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
export const OUT_DIR = join(ROOT, "templates", "tcenter-sales", "code-nodes");

/** A module's source as plain script: no import lines, no `export` keywords. */
function inline(rel) {
  const src = readFileSync(join(ROOT, rel), "utf8");
  return src
    .split("\n")
    .filter((l) => !/^\s*import\s[^;]*from\s+["'][^"']+["'];?\s*$/.test(l))
    .join("\n")
    .replace(/^export\s+/gm, "");
}

const banner = (name, modules) =>
  `// ===== ${name} — GENERATED by scripts/n8n/build-tcenter-nodes.mjs =====\n` +
  `// Source: ${modules.join(" + ")}. Do not edit here: change the module, rebuild, re-paste.\n`;

const section = (rel) => `\n// ---- ${rel} ----\n${inline(rel)}\n`;

/** Each node: which modules it inlines and the node-specific glue that runs last. */
const NODES = {
  "classify-takeover.js": {
    title: "Classify Takeover (owner wrote from the business number)",
    modules: ["lib/bot/callback-time.mjs", "lib/bot/takeover.mjs"],
    glue: `
// ---- node ----
// Input: "Takeover: Read Current" (Supabase getAll human_mode by chat_id, Always Output Data ON).
const msg = $('Webhook (WHAPI In)').first().json.body.messages[0];
const current = $input.all().map((i) => i.json).find((r) => r && r.chat_id) || null;
let d;
try { d = decideTakeover(msg, new Date(), current); }
catch (e) { d = { action: 'silence', kind: 'handling', reason: 'error: ' + String(e && e.message || e), row: { active: true, silenced_until: new Date(Date.now() + TAKEOVER_CONFIG.handlingMinutes * 60000).toISOString() } }; }
if (d.action === 'ignore') return [];
return [{ json: {
  chatId: msg.chat_id,
  active: d.row.active,
  silencedUntil: d.row.silenced_until,
  takeoverKind: d.kind,
  takeoverReason: d.reason,
} }];
`,
  },

  "friction-gate.js": {
    title: "Friction Gate (before the agent answers)",
    modules: ["lib/bot/friction.mjs"],
    glue: `
// ---- node ----
// Between "Language Gate (Hebrew)" and the agent. Passes its input through untouched (the
// agent reads $('Draft: Context')); adds friction* fields only. History = "Mem: Load History",
// already loaded this turn (newest 40, current turn excluded, Always Output Data ON).
const input = $input.first().json;
// Fail open: if anything here throws, the agent answers exactly as before this node existed.
try {
const turn = $('Bot Allowed?').first().json;
// Mem: Load History already excludes this turn (message_id != turnKey): drop nothing as "part of the
// current message", or a customer repeating "לא הבנתי" would never count twice.
const history = historyBefore($('Mem: Load History').all().map((i) => i.json), '');
const d = decideFriction({ text: turn.mergedText, history, now: new Date(), businessOpen: turn.businessOpen !== false });
const phone = String(turn.chatId || '').split('@')[0];
return [{ json: {
  ...input,
  frictionAction: d.action,            // continue | handoff
  frictionReason: d.reason,
  frictionSignals: d.signals,
  frictionChatId: turn.chatId,
  frictionReply: d.reply,              // the one line the customer gets (handoff only)
  frictionAlert: d.action === 'handoff' ? groupAlert({ reason: d.reason, name: turn.senderName, phone, lastText: turn.mergedText }) : null,
  frictionSilencedUntil: new Date(Date.now() + FRICTION_CONFIG.holdHours * 3600000).toISOString(),
  // What "Friction: Save Turn" stores, the way Mem: Build Turn does: the customer's words, no system note.
  frictionMemUser: String(turn.rawText != null ? turn.rawText : (turn.mergedText || '')).replace(/\\[המערכת:[^\\]]*\\]/g, '').trim(),
  frictionTurnKey: turn.turnKey || null,
}, pairedItem: { item: 0 } }];
} catch (e) {
  return [{ json: { ...input, frictionAction: 'continue', frictionError: String(e && e.message || e) }, pairedItem: { item: 0 } }];
}
`,
  },

  "repeat-guard.js": {
    title: "Repeat Guard (between Parse Order and Send Summary / Reply)",
    modules: ["lib/bot/friction.mjs"],
    glue: `
// ---- node ----
// Input: "Parse Order". A blocked reply is not sent: the turn goes to "Mem: Save Silenced Inbound"
// (needs chatId / rawText / turnKey) and, at most every 30 min per chat, a card to the orders group.
const p = $input.first().json;
// Fail open: if anything here throws, the reply is sent exactly as before this node existed.
try {
const turn = $('Bot Allowed?').first().json;
const history = historyBefore($('Mem: Load History').all().map((i) => i.json), ''); // this turn is already excluded
const g = repeatGuard({ reply: p.summary, isOrder: p.isOrder, history, now: new Date() });
if (!g.blocked) return [{ json: { ...p, repeatBlocked: false }, pairedItem: { item: 0 } }];
const phone = String(turn.chatId || '').split('@')[0];
const sd = $getWorkflowStaticData('global');
sd.repeatAlerts = sd.repeatAlerts || {};
for (const k in sd.repeatAlerts) if (Date.now() - sd.repeatAlerts[k] > 24 * 3600000) delete sd.repeatAlerts[k];
const notify = Date.now() - (sd.repeatAlerts[phone] || 0) >= 30 * 60000;
if (notify) sd.repeatAlerts[phone] = Date.now();
return [{ json: {
  ...p,
  repeatBlocked: true,
  chatId: turn.chatId,
  rawText: String(turn.rawText != null ? turn.rawText : (turn.mergedText || '')).replace(/\\[המערכת:[^\\]]*\\]/g, '').trim(),
  turnKey: turn.turnKey || null,
  frictionAlert: notify ? groupAlert({ reason: 'still_waiting', name: turn.senderName, phone, lastText: turn.mergedText, silenced: false }) : '',
}, pairedItem: { item: 0 } }];
} catch (e) {
  return [{ json: { ...p, repeatBlocked: false, repeatError: String(e && e.message || e) }, pairedItem: { item: 0 } }];
}
`,
  },

  "group-bot-command.js": {
    title: "Group Bot Command (owner replies 'בוט' / 'שקט' in the orders group)",
    modules: ["lib/bot/callback-time.mjs", "lib/bot/takeover.mjs"],
    glue: `
// ---- node ----
const m = $('Webhook (WHAPI In)').first().json.body.messages[0];
const text = (m.text && m.text.body) || '';
const q = (m.context && m.context.quoted_content) || '';
const quoted = typeof q === 'string' ? q : (q.body || (q.text && q.text.body) || q.caption || '');
const cmd = parseGroupCommand(text, quoted);
if (!cmd) return [];
const now = new Date();
const until = cmd.action === 'release'
  ? now
  : fromWallClock(partsOf(now).y, partsOf(now).m, partsOf(now).d + 1, 0, 0);
return [{ json: {
  chatId: cmd.chatId,
  active: cmd.action !== 'release',
  silencedUntil: until.toISOString(),
  confirm: cmd.action === 'release'
    ? '✅ הבוט חזר לענות ל-' + cmd.chatId.split('@')[0]
    : '🔇 הבוט מושתק עד מחר ל-' + cmd.chatId.split('@')[0],
} }];
`,
  },
};

/** @returns {Record<string, string>} file name → node source */
export function buildNodes() {
  /** @type {Record<string, string>} */
  const out = {};
  for (const [file, n] of Object.entries(NODES)) {
    out[file] = banner(n.title, n.modules) + n.modules.map(section).join("") + n.glue;
  }
  return out;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const check = process.argv.includes("--check");
  const built = buildNodes();
  let stale = 0;
  mkdirSync(OUT_DIR, { recursive: true });
  for (const [file, code] of Object.entries(built)) {
    const path = join(OUT_DIR, file);
    let current = null;
    try { current = readFileSync(path, "utf8"); } catch { /* new file */ }
    if (current === code) continue;
    if (check) { console.error(`stale: ${file}`); stale++; continue; }
    writeFileSync(path, code);
    console.log(`wrote ${file}`);
  }
  if (check && stale) process.exit(1);
}
